const COURSE_LESSON_HTML = {
  "kurssArticlesLesson": "\n  <h3>Névelők</h3>\n\n  <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>A német névelőt nem lehet a magyar alapján kitalálni, hiszen a magyarban nincs nyelvtani nem. Ezért a főneveket a legjobb a névelőjükkel együtt tanulni.</div>\n  </div>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Példák a névelőkre</h4>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">der Tisch — asztal</div>\n      <div class=\"kurss-example\">die Tür — ajtó</div>\n      <div class=\"kurss-example\">das Messer — kés</div>\n      <div class=\"kurss-example\">das Mädchen — lány</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♂</span>Gyakran DER</h4>\n    <p class=\"artikuli-explain\">DER gyakran: férfi személyek, napok, hónapok, évszakok és néhány bizonyos végződésű szó.</p>\n\n    <h5 class=\"artikuli-subtitle\">Szabályok</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-er → gyakran DER, például: der Computer, der Lehrer <span class=\"artikuli-note\">de nem mindig</span></div>\n      <div class=\"kurss-example\">-ling → gyakran DER, például: der Schmetterling</div>\n      <div class=\"kurss-example\">-ismus → gyakran DER, például: der Tourismus, der Kapitalismus</div>\n      <div class=\"kurss-example\">férfi személyek → der Mann, der Vater</div>\n      <div class=\"kurss-example\">foglalkozások → der Lehrer, der Arzt</div>\n      <div class=\"kurss-example\">autómárkák → der BMW, der Mercedes</div>\n      <div class=\"kurss-example\">napok → der Montag, der Dienstag</div>\n      <div class=\"kurss-example\">hónapok → der August, der Dezember</div>\n      <div class=\"kurss-example\">évszakok → der Sommer, der Winter</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Példák</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">der Mann — férfi</div>\n      <div class=\"kurss-example\">der Vater — apa</div>\n      <div class=\"kurss-example\">der Montag — hétfő</div>\n      <div class=\"kurss-example\">der August — augusztus</div>\n      <div class=\"kurss-example\">der Sommer — nyár</div>\n      <div class=\"kurss-example\">der Lehrer — tanár</div>\n      <div class=\"kurss-example\">der Computer — számítógép</div>\n      <div class=\"kurss-example\">der Schmetterling — pillangó</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♀</span>Gyakran DIE</h4>\n    <p class=\"artikuli-explain\">DIE gyakran: női személyek, a többes szám, valamint az -ung, -heit, -keit, -schaft, -ion, -tät, -ei végződésű szavak.</p>\n\n    <h5 class=\"artikuli-subtitle\">Szabályok</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-ung → die Wohnung, die Rechnung</div>\n      <div class=\"kurss-example\">-heit → die Freiheit, die Gesundheit</div>\n      <div class=\"kurss-example\">-keit → die Möglichkeit</div>\n      <div class=\"kurss-example\">-schaft → die Mannschaft</div>\n      <div class=\"kurss-example\">-ion → die Nation</div>\n      <div class=\"kurss-example\">-tät → die Universität</div>\n      <div class=\"kurss-example\">-ei → die Polizei, die Bäckerei</div>\n      <div class=\"kurss-example\">női személyek → die Frau, die Mutter</div>\n      <div class=\"kurss-example\">motormárkák → die Harley-Davidson, die Yamaha</div>\n      <div class=\"kurss-example\">többes szám → die Autos, die Häuser</div>\n      <div class=\"kurss-example\">többes szám szinte mindig → die Autos, die Häuser, die Kinder</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Példák</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">die Frau — nő</div>\n      <div class=\"kurss-example\">die Mutter — anya</div>\n      <div class=\"kurss-example\">die Wohnung — lakás</div>\n      <div class=\"kurss-example\">die Rechnung — számla</div>\n      <div class=\"kurss-example\">die Freiheit — szabadság</div>\n      <div class=\"kurss-example\">die Möglichkeit — lehetőség</div>\n      <div class=\"kurss-example\">die Mannschaft — csapat</div>\n      <div class=\"kurss-example\">die Nation — nemzet</div>\n      <div class=\"kurss-example\">die Universität — egyetem</div>\n      <div class=\"kurss-example\">die Polizei — rendőrség</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>◇</span>Gyakran DAS</h4>\n    <p class=\"artikuli-explain\">DAS gyakran: a -chen / -lein kicsinyítő képzős szavak, sok -ment / -um végződésű szó, valamint a főnévként használt igék.</p>\n\n    <h5 class=\"artikuli-subtitle\">Szabályok</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-chen → das Mädchen, das Häuschen</div>\n      <div class=\"kurss-example\">-lein → das Fräulein</div>\n      <div class=\"kurss-example\">-ment → das Instrument</div>\n      <div class=\"kurss-example\">-um → das Zentrum, das Museum</div>\n      <div class=\"kurss-example\">fémek → das Gold, das Silber, das Eisen</div>\n      <div class=\"kurss-example\">kémiai elemek → das Eisen, das Kupfer</div>\n      <div class=\"kurss-example\">szállodák → das Hotel</div>\n      <div class=\"kurss-example\">főnévként használt színek → das Rot, das Blau</div>\n      <div class=\"kurss-example\">főnévként használt ige → das Essen, das Lernen</div>\n      <div class=\"kurss-example\">főnévként használt igék → das Essen, das Lernen, das Lesen</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Példák</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">das Kind — gyerek</div>\n      <div class=\"kurss-example\">das Mädchen — lány</div>\n      <div class=\"kurss-example\">das Häuschen — házikó</div>\n      <div class=\"kurss-example\">das Instrument — hangszer</div>\n      <div class=\"kurss-example\">das Zentrum — központ</div>\n      <div class=\"kurss-example\">das Museum — múzeum</div>\n      <div class=\"kurss-example\">das Essen — evés / étel</div>\n      <div class=\"kurss-example\">das Lernen — tanulás</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>!</span>Fontos kivételek / névelővel együtt tanulandó</h4>\n    <p class=\"artikuli-explain\">Egyes szavak névelőjét nem lehet biztosan meghatározni a végződés vagy a magyar szó alapján (a magyarban nincs nyelvtani nem). Ezeket a legjobb a névelőjükkel együtt tanulni.</p>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">die Tür — ajtó</div>\n      <div class=\"kurss-example\">das Messer — kés</div>\n      <div class=\"kurss-example\">die Sonne — nap</div>\n      <div class=\"kurss-example\">der Mond — hold</div>\n      <div class=\"kurss-example\">das Mädchen — lány</div>\n      <div class=\"kurss-example\">das Auto — autó</div>\n      <div class=\"kurss-example\">der Käse — sajt</div>\n      <div class=\"kurss-example\">die Gabel — villa</div>\n    </div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>A végződések és a szócsoportok segítenek kitalálni a névelőt, de ezek nem 100%-ig biztos szabályok. Ha nem vagy biztos benne, tanuld a szót a névelőjével együtt.</div>\n  </div>\n",
  "kurssPronounsLesson": "\n  <h3>Névmások</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nominativ, Akkusativ és Dativ — a névmások alakjai.</div>\n  </div>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>N</span>Nominativ — ki?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich — én</div><div class=\"kurss-example\">du — te</div><div class=\"kurss-example\">er — ő</div><div class=\"kurss-example\">sie — ő</div><div class=\"kurss-example\">es — az</div><div class=\"kurss-example\">wir — mi</div><div class=\"kurss-example\">ihr — ti</div><div class=\"kurss-example\">sie — ők</div><div class=\"kurss-example\">Sie — Ön (udvarias)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>A</span>Akkusativ — kit?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mich — engem</div><div class=\"kurss-example\">dich — téged</div><div class=\"kurss-example\">ihn — őt (hímn.)</div><div class=\"kurss-example\">sie — őt (nőn.)</div><div class=\"kurss-example\">es — azt</div><div class=\"kurss-example\">uns — minket</div><div class=\"kurss-example\">euch — titeket</div><div class=\"kurss-example\">sie — őket</div><div class=\"kurss-example\">Sie — Önt (udvarias)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>D</span>Dativ — kinek?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mir — nekem</div><div class=\"kurss-example\">dir — neked</div><div class=\"kurss-example\">ihm — neki / annak</div><div class=\"kurss-example\">ihr — neki</div><div class=\"kurss-example\">uns — nekünk</div><div class=\"kurss-example\">euch — nektek</div><div class=\"kurss-example\">ihnen — nekik</div><div class=\"kurss-example\">Ihnen — Önnek (udvarias)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>?</span>Hogyan válasszuk ki az alakot?</h4>\n    <ul class=\"kurss-summary-list\"><li><span class=\"case-blue\">Nominativ</span> — a mondat alanya (ki cselekszik?)</li><li><span class=\"case-red\">Akkusativ</span> — tárgy (kit?)</li><li><span class=\"case-green\">Dativ</span> — részeshatározó (kinek?)</li></ul>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Példák</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">dich</span>. — Látlak.</div><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">ihn</span>. — Látom őt.</div><div class=\"kurss-example\">Wir mögen <span class=\"case-red\">euch</span>. — Kedvelünk titeket.</div><div class=\"kurss-example\">Ich helfe <span class=\"case-green\">dir</span>. — Segítek neked.</div><div class=\"kurss-example\">Ich gebe <span class=\"case-green\">ihm</span> ein Buch. — Adok neki egy könyvet.</div><div class=\"kurss-example\">Wir danken <span class=\"case-green\">euch</span>. — Köszönjük nektek.</div></div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>A Nominativ mindig a mondat alanya, az Akkusativ és a Dativ pedig a mondat bővítményei. Nézd meg az igét, és kérdezd: <span class=\"case-red\">kit?</span> vagy <span class=\"case-green\">kinek?</span></div>\n  </div>\n",
  "kurssPronunciationLesson": "\n            <h3>Magánhangzók — hosszú és rövid</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n              <span class=\"artikuli-info-icon\">i</span>\n              <div>A németben a magánhangzók lehetnek hosszúak vagy rövidek. Ez befolyásolja a szó kiejtését.</div>\n            </div>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Hosszú magánhangzó</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">warm (varm) — meleg</div><div class=\"kurss-example\">gut (gút) — jó</div><div class=\"kurss-example\">Tat (tát) — tett / cselekedet</div><div class=\"kurss-example\">Flur (flúr) — folyosó / előszoba</div><div class=\"kurss-example\">Weg (vék) — út</div><div class=\"kurss-example\">Hut (hút) — kalap</div><div class=\"kurss-example\">Hof (hóf) — udvar</div><div class=\"kurss-example\">Schlaf (sláf) — alvás</div></div>\n              <p class=\"artikuli-explain\">Ha a magánhangzót egy mássalhangzó követi, a magánhangzót gyakran hosszan ejtjük.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Rövid magánhangzó</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Pilz (pilc) — gomba</div><div class=\"kurss-example\">Wort (vort) — szó</div><div class=\"kurss-example\">Mund (munt) — száj</div><div class=\"kurss-example\">bald (balt) — hamarosan</div><div class=\"kurss-example\">scharf (sarf) — éles / csípős</div><div class=\"kurss-example\">Feld (felt) — mező</div><div class=\"kurss-example\">voll (fol) — tele / teli</div></div>\n              <p class=\"artikuli-explain\">Ha a magánhangzót két vagy több mássalhangzó követi, a magánhangzót gyakran röviden ejtjük.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Az en / el / er végződések</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">singen (zingen) — énekelni</div><div class=\"kurss-example\">tragen (trágen) — vinni / hordani</div><div class=\"kurss-example\">Garten (garten) — kert</div><div class=\"kurss-example\">Vogel (fógel) — madár</div><div class=\"kurss-example\">Segel (zégel) — vitorla</div><div class=\"kurss-example\">Braten (bráten) — sült (hús)</div><div class=\"kurss-example\">Bogen (bógen) — ív / íj</div><div class=\"kurss-example\">Spiegel (spígel) — tükör</div><div class=\"kurss-example\">Finger (finger) — ujj</div><div class=\"kurss-example\">Halter (halter) — tartó</div><div class=\"kurss-example\">Arbeiter (arbájter) — munkás</div><div class=\"kurss-example\">Häuser (hojzer) — házak</div><div class=\"kurss-example\">wieder (víder) — újra / ismét</div><div class=\"kurss-example\">breiter (brájter) — szélesebb</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>A h betű mint hosszúságjel</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Rahmen (rámen) — keret</div><div class=\"kurss-example\">Ohr (ór) — fül</div><div class=\"kurss-example\">Kohle (kóle) — szén</div><div class=\"kurss-example\">Zahl (cál) — szám</div><div class=\"kurss-example\">ihn (ín) — őt</div><div class=\"kurss-example\">ihm (ím) — neki</div><div class=\"kurss-example\">Huhn (hún) — tyúk</div><div class=\"kurss-example\">nahm (nám) — vett / fogott</div><div class=\"kurss-example\">nehmen (némen) — venni / fogni</div><div class=\"kurss-example\">Schuh (sú) — cipő</div></div>\n              <p class=\"artikuli-explain\">Egyes szavakban a h meghosszabbítja az előtte álló magánhangzót. Ilyenkor a h-t általában nem ejtjük.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Végződések e-vel</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Lampe (lampe) — lámpa</div><div class=\"kurss-example\">Hase (háze) — nyúl (mezei nyúl)</div><div class=\"kurss-example\">Knabe (knábe) — fiú</div><div class=\"kurss-example\">Rabe (rábe) — holló</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>A hosszú i = ie</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">die (dí) — a „die” névelő</div><div class=\"kurss-example\">diese (díze) — ez / ezek</div><div class=\"kurss-example\">wieder (víder) — újra / ismét</div><div class=\"kurss-example\">Fliege (flíge) — légy</div><div class=\"kurss-example\">Ziege (cíge) — kecske</div><div class=\"kurss-example\">Stiel (stíl) — szár / nyél</div><div class=\"kurss-example\">Dieb (díp) — tolvaj</div><div class=\"kurss-example\">hier (hír) — itt</div></div>\n              <p class=\"artikuli-explain\">A hosszú i-t a németben gyakran ie-vel írják.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Kettőzött magánhangzók</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Saal (zál) — terem</div><div class=\"kurss-example\">Saat (zát) — vetés / vetőmag</div><div class=\"kurss-example\">Staat (stát) — állam</div><div class=\"kurss-example\">Beere (bére) — bogyó</div><div class=\"kurss-example\">See (zé) — tó / tenger</div><div class=\"kurss-example\">Beet (bét) — ágyás</div><div class=\"kurss-example\">Boot (bót) — csónak</div><div class=\"kurss-example\">Moor (mór) — láp</div><div class=\"kurss-example\">Moos (mósz) — moha</div></div>\n              <p class=\"artikuli-explain\">A kettőzött magánhangzókat általában hosszan ejtjük.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ä</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Wand (vant) — fal</div><div class=\"kurss-example\">Wände (vende) — falak</div><div class=\"kurss-example\">Vater (fáter) — apa</div><div class=\"kurss-example\">Väter (féter) — apák</div><div class=\"kurss-example\">Schrank (srank) — szekrény</div><div class=\"kurss-example\">Schränke (srenke) — szekrények</div><div class=\"kurss-example\">Bank (bank) — pad / bank</div><div class=\"kurss-example\">Bänke (benke) — padok</div><div class=\"kurss-example\">Tal (tál) — völgy</div><div class=\"kurss-example\">Täler (téler) — völgyek</div></div>\n              <p class=\"artikuli-explain\">Az ä az a umlautos (hangváltott) alakja.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ö</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Rose (róze) — rózsa</div><div class=\"kurss-example\">Röschen (rőszhen) — rózsácska</div><div class=\"kurss-example\">Ofen (ófen) — kályha / sütő</div><div class=\"kurss-example\">Öfen (őfen) — kályhák / sütők</div><div class=\"kurss-example\">Rock (rok) — szoknya</div><div class=\"kurss-example\">Röcke (röke) — szoknyák</div></div>\n              <p class=\"artikuli-explain\">Az ö az o umlautos (hangváltott) alakja.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ü</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">kurz (kurc) — rövid</div><div class=\"kurss-example\">kürzer (kürcer) — rövidebb</div><div class=\"kurss-example\">Kunst (kunszt) — művészet</div><div class=\"kurss-example\">Künste (künszte) — művészetek</div><div class=\"kurss-example\">Mutter (muter) — anya</div><div class=\"kurss-example\">Mütter (müter) — anyák</div></div>\n              <p class=\"artikuli-explain\">Az ü az u umlautos (hangváltott) alakja.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Kettőshangzók: äu</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Baum (baum) — fa</div><div class=\"kurss-example\">Bäume (bojme) — fák</div><div class=\"kurss-example\">Haus (hausz) — ház</div><div class=\"kurss-example\">Häuser (hojzer) — házak</div><div class=\"kurss-example\">Strauch (strauh) — bokor / cserje</div><div class=\"kurss-example\">Sträucher (strojher) — bokrok / cserjék</div><div class=\"kurss-example\">Maus (mausz) — egér</div><div class=\"kurss-example\">Mäuse (mojze) — egerek</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Kettőshangzók: eu</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">heute (hojte) — ma</div><div class=\"kurss-example\">Leute (lojte) — emberek</div><div class=\"kurss-example\">neu (noj) — új</div><div class=\"kurss-example\">neun (nojn) — kilenc</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Kettőshangzók: ei</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">mein (májn) — az enyém / -m</div><div class=\"kurss-example\">dein (dájn) — a tiéd / -d</div><div class=\"kurss-example\">sein (zájn) — (az ő) …-a/-e (hímnemű/semleges birtokos) / lenni</div><div class=\"kurss-example\">frei (fráj) — szabad</div><div class=\"kurss-example\">arbeiten (arbájten) — dolgozni</div></div>\n            </section>\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>✓</span>A 2. óra kiejtési megjegyzései</h4>\n              <ul class=\"kurss-summary-list\"><li>az ich, nicht, rechnen, zeichnen szavakban a „ch”-t lágyan ejtjük (mint a „h”-t az „ihlet” szóban)</li><li>az arbeiten és zeichnen szavakban az „ei”-t „aj”-nak ejtjük</li><li>az „sp”-t a szó elején magyar s-sel, „sp”-nek ejtjük (mint a „spárga” szóban), nem „szp”-nek</li><li>a tun igében az „u” betűt hosszan ejtjük („ú”)</li></ul>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>✓</span>Összefoglalás</h4>\n              <ul class=\"kurss-summary-list\"><li>egy mássalhangzó a magánhangzó után → gyakran hosszú magánhangzó</li><li>két vagy több mássalhangzó → gyakran rövid magánhangzó</li><li>a h meghosszabbíthatja a magánhangzót</li><li>az ie gyakran hosszú i-t jelent</li><li>a kettőzött magánhangzók általában hosszúak</li></ul>\n            </section>",
  "kurssConsonantsLesson": "\n            <h3>Mássalhangzók és betűkombinációk</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n              <span class=\"artikuli-info-icon\">i</span>\n              <div>A németben egyes mássalhangzókat és betűkombinációkat másképp ejtünk, mint ahogy írjuk őket. Ebben a leckében a kezdők számára legfontosabb példák szerepelnek.</div>\n            </div>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Mássalhangzók</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">das Rad (dasz rát) — kerék</div><div class=\"kurss-example\">die Räder (dí réder) — kerekek</div><div class=\"kurss-example\">Bad (bát) — fürdő / fürdőszoba</div><div class=\"kurss-example\">Bäder (béder) — fürdők / fürdőszobák</div></div>\n              <p class=\"artikuli-explain\">A szó végén a mássalhangzókat gyakran nem úgy ejtjük, ahogy írjuk (pl. a d „t”-nek hangzik).</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ch</h4>\n              <p class=\"artikuli-explain\">A „ch”-t ejthetjük lágyan vagy keményen. Egyes szavakban lágy „h”-nak hangzik (mint az „ihlet” szóban), másokban keményebb, torokban képzett hang, amely közelebb áll a „k”-hoz.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">rechnen (rehnen) — számolni</div><div class=\"kurss-example\">zeichnen (cájhnen) — rajzolni</div><div class=\"kurss-example\">nicht (niht) — nem</div><div class=\"kurss-example\">schlecht (sleht) — rossz</div><div class=\"kurss-example\">mich (mih) — engem</div><div class=\"kurss-example\">dich (dih) — téged</div><div class=\"kurss-example\">Strauch (strauh) — bokor / cserje</div><div class=\"kurss-example\">noch (noh) — még</div><div class=\"kurss-example\">Nacht (naht) — éjszaka</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>sch</h4>\n              <p class=\"artikuli-explain\">A németben az „sch”-t úgy ejtjük, mint a magyar „s”-t (mint a „sas” szóban).</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Schule (súle) — iskola</div><div class=\"kurss-example\">Schüler (súler) — tanuló / diák</div><div class=\"kurss-example\">Schiff (sif) — hajó</div><div class=\"kurss-example\">Schraube (sraube) — csavar</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>sp és st a szó elején</h4>\n              <p class=\"artikuli-explain\">A szó vagy szótag elején az „sp”-t és „st”-t gyakran magyar s-sel ejtjük: „sp”, „st” (mint a „spárga” és a „strand” szóban), nem „szp”, „szt”.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">spielen (spílen) — játszani</div><div class=\"kurss-example\">Sprung (sprung) — ugrás</div><div class=\"kurss-example\">stehen (stéen) — állni</div><div class=\"kurss-example\">Stall (stal) — istálló</div><div class=\"kurss-example\">Stand (stant) — állás / stand (árusítóhely)</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>qu</h4>\n              <p class=\"artikuli-explain\">A németben a „qu”-t általában „kv”-nek ejtjük.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Qual (kvál) — kín / gyötrelem</div><div class=\"kurss-example\">Quartier (kvartír) — szállás / városnegyed</div><div class=\"kurss-example\">quer (kvér) — keresztben / haránt</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>s és z</h4>\n              <p class=\"artikuli-explain\">A szó elején az „s” gyakran „z”-nek hangzik. A „z” betű a németben úgy hangzik, mint a magyar „c”.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">sagen (zágen) — mondani</div><div class=\"kurss-example\">singen (zingen) — énekelni</div><div class=\"kurss-example\">Rose (róze) — rózsa</div><div class=\"kurss-example\">Zahl (cál) — szám</div><div class=\"kurss-example\">Zeit (cájt) — idő</div><div class=\"kurss-example\">Zink (cink) — cink</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>v</h4>\n              <p class=\"artikuli-explain\">A németben a „v”-t gyakran „f”-nek ejtjük. Idegen szavakban gyakran úgy hangzik, mint a magyar „v”.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Vater (fáter) — apa</div><div class=\"kurss-example\">von (fon) — -tól/-től / -ból/-ből</div><div class=\"kurss-example\">viel (fíl) — sok</div><div class=\"kurss-example\">vier (fír) — négy</div><div class=\"kurss-example\">Villa (vila) — villa</div><div class=\"kurss-example\">Klavier (klavír) — zongora</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>x és y</h4>\n              <p class=\"artikuli-explain\">Az „x”-et „ksz”-nek ejtjük. Az „y”-t egyes szavakban „ü”-nek ejtjük.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Felix (féliksz) — Félix (férfinév)</div><div class=\"kurss-example\">Axt (akszt) — fejsze</div><div class=\"kurss-example\">Mystik (müsztik) — misztika</div><div class=\"kurss-example\">Mythe (müte) — mítosz</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ß</h4>\n              <p class=\"artikuli-explain\">A németben a „ß”-t úgy ejtjük, mint a magyar „sz”-t.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Fuß (fúsz) — láb / lábfej</div><div class=\"kurss-example\">Füße (füsze) — lábak / lábfejek</div><div class=\"kurss-example\">Grüße (grüsze) — üdvözlet / üdvözletek</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>✓</span>Összefoglalás</h4>\n              <ul class=\"kurss-summary-list\"><li>sch → s</li><li>sp / st a szó elején → sp / st (magyar s-sel)</li><li>qu → kv</li><li>z → c</li><li>v gyakran → f</li><li>x → ksz</li><li>ß → sz</li></ul>\n            </section>",
  "kurssVerbBasicsLesson": "\n            <h3>Az igék alapjai</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n              <span class=\"artikuli-info-icon\">i</span>\n              <div>Az 1. lecke igéi és ragozásuk (konjugáció)</div>\n            </div>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Igék</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">kommen — jönni</div><div class=\"kurss-example\">gehen — menni</div><div class=\"kurss-example\">stehen — állni</div><div class=\"kurss-example\">singen — énekelni</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>kommen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich komme — én jövök</div><div class=\"kurss-example\">du kommst — te jössz</div><div class=\"kurss-example\">er kommt — ő jön</div><div class=\"kurss-example\">sie kommt — ő jön</div><div class=\"kurss-example\">wir kommen — mi jövünk</div><div class=\"kurss-example\">ihr kommt — ti jöttök</div><div class=\"kurss-example\">sie kommen — ők jönnek</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>gehen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich gehe — én megyek</div><div class=\"kurss-example\">du gehst — te mész</div><div class=\"kurss-example\">er geht — ő megy</div><div class=\"kurss-example\">sie geht — ő megy</div><div class=\"kurss-example\">wir gehen — mi megyünk</div><div class=\"kurss-example\">ihr geht — ti mentek</div><div class=\"kurss-example\">sie gehen — ők mennek</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>stehen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich stehe — én állok</div><div class=\"kurss-example\">du stehst — te állsz</div><div class=\"kurss-example\">er steht — ő áll</div><div class=\"kurss-example\">sie steht — ő áll</div><div class=\"kurss-example\">wir stehen — mi állunk</div><div class=\"kurss-example\">ihr steht — ti álltok</div><div class=\"kurss-example\">sie stehen — ők állnak</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>singen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich singe — én énekelek</div><div class=\"kurss-example\">du singst — te énekelsz</div><div class=\"kurss-example\">er singt — ő énekel</div><div class=\"kurss-example\">sie singt — ő énekel</div><div class=\"kurss-example\">wir singen — mi énekelünk</div><div class=\"kurss-example\">ihr singt — ti énekeltek</div><div class=\"kurss-example\">sie singen — ők énekelnek</div></div>\n            </section>\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>A 2. lecke igéi</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">spielen — játszani</div><div class=\"kurss-example\">arbeiten — dolgozni</div><div class=\"kurss-example\">fragen — kérdezni</div><div class=\"kurss-example\">antworten — válaszolni</div><div class=\"kurss-example\">rechnen — számolni</div><div class=\"kurss-example\">zeichnen — rajzolni</div><div class=\"kurss-example\">tun — csinálni</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>spielen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich spiele — én játszom</div><div class=\"kurss-example\">du spielst — te játszol</div><div class=\"kurss-example\">er spielt — ő játszik</div><div class=\"kurss-example\">sie spielt — ő játszik</div><div class=\"kurss-example\">wir spielen — mi játszunk</div><div class=\"kurss-example\">ihr spielt — ti játszotok</div><div class=\"kurss-example\">sie spielen — ők játszanak</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>arbeiten</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich arbeite — én dolgozom</div><div class=\"kurss-example\">du arbeitest — te dolgozol</div><div class=\"kurss-example\">er arbeitet — ő dolgozik</div><div class=\"kurss-example\">sie arbeitet — ő dolgozik</div><div class=\"kurss-example\">wir arbeiten — mi dolgozunk</div><div class=\"kurss-example\">ihr arbeitet — ti dolgoztok</div><div class=\"kurss-example\">sie arbeiten — ők dolgoznak</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>fragen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich frage — én kérdezek</div><div class=\"kurss-example\">du fragst — te kérdezel</div><div class=\"kurss-example\">er fragt — ő kérdez</div><div class=\"kurss-example\">sie fragt — ő kérdez</div><div class=\"kurss-example\">wir fragen — mi kérdezünk</div><div class=\"kurss-example\">ihr fragt — ti kérdeztek</div><div class=\"kurss-example\">sie fragen — ők kérdeznek</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>antworten</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich antworte — én válaszolok</div><div class=\"kurss-example\">du antwortest — te válaszolsz</div><div class=\"kurss-example\">er antwortet — ő válaszol</div><div class=\"kurss-example\">sie antwortet — ő válaszol</div><div class=\"kurss-example\">wir antworten — mi válaszolunk</div><div class=\"kurss-example\">ihr antwortet — ti válaszoltok</div><div class=\"kurss-example\">sie antworten — ők válaszolnak</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>rechnen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich rechne — én számolok</div><div class=\"kurss-example\">du rechnest — te számolsz</div><div class=\"kurss-example\">er rechnet — ő számol</div><div class=\"kurss-example\">sie rechnet — ő számol</div><div class=\"kurss-example\">wir rechnen — mi számolunk</div><div class=\"kurss-example\">ihr rechnet — ti számoltok</div><div class=\"kurss-example\">sie rechnen — ők számolnak</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>zeichnen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich zeichne — én rajzolok</div><div class=\"kurss-example\">du zeichnest — te rajzolsz</div><div class=\"kurss-example\">er zeichnet — ő rajzol</div><div class=\"kurss-example\">sie zeichnet — ő rajzol</div><div class=\"kurss-example\">wir zeichnen — mi rajzolunk</div><div class=\"kurss-example\">ihr zeichnet — ti rajzoltok</div><div class=\"kurss-example\">sie zeichnen — ők rajzolnak</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>tun</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich tue — én csinálok</div><div class=\"kurss-example\">du tust — te csinálsz</div><div class=\"kurss-example\">er tut — ő csinál</div><div class=\"kurss-example\">sie tut — ő csinál</div><div class=\"kurss-example\">wir tun — mi csinálunk</div><div class=\"kurss-example\">ihr tut — ti csináltok</div><div class=\"kurss-example\">sie tun — ők csinálnak</div></div>\n            </section>",
  "kurssSentenceStructureLesson": "\n            <h3>Mondatszerkezet</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n              <span class=\"artikuli-info-icon\">i</span>\n              <div>Kérdő mondatban a német nyelvben az ige általában az első helyen áll.</div>\n            </div>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Példák</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Du kommst. — Jössz.</div><div class=\"kurss-example\">Kommst du? — Jössz?</div><div class=\"kurss-example\">Er singt. — Ő énekel.</div><div class=\"kurss-example\">Singt er? — Énekel ő?</div><div class=\"kurss-example\">Stehst du? — Állsz?</div><div class=\"kurss-example\">Ja, ich stehe. — Igen, állok.</div><div class=\"kurss-example\">Geht ihr? — Mentek?</div><div class=\"kurss-example\">Ja, wir gehen. — Igen, megyünk.</div></div>\n            </section>\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Kérdések „was” kérdőszóval</h4>\n              <p class=\"artikuli-explain\">Ha a kérdés kérdőszóval kezdődik, az ige a német nyelvben általában közvetlenül a kérdőszó után áll.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Was tust du? — Mit csinálsz?</div><div class=\"kurss-example\">Was tut er? — Mit csinál ő?</div><div class=\"kurss-example\">Was tut sie? — Mit csinál ő?</div><div class=\"kurss-example\">Was tun sie? — Mit csinálnak ők?</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Tagadás „nicht” szóval</h4>\n              <p class=\"artikuli-explain\">Ha a „nicht” tagadószó az igére vonatkozik, a német nyelvben általában az ige után áll.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Ich spiele nicht. — Nem játszom.</div><div class=\"kurss-example\">Paul fragt nicht. — Paul nem kérdez.</div><div class=\"kurss-example\">Er kommt nicht. — Ő nem jön.</div><div class=\"kurss-example\">Sie singen nicht. — Ők nem énekelnek.</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Mondatok a 2. leckéből</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Spielst du? — Játszol?</div><div class=\"kurss-example\">Nein, ich spiele nicht, ich arbeite. — Nem, nem játszom, dolgozom.</div><div class=\"kurss-example\">Paul fragt nicht, er arbeitet. — Paul nem kérdez, dolgozik.</div><div class=\"kurss-example\">Arbeitest du? — Dolgozol?</div><div class=\"kurss-example\">Nein, ich arbeite nicht, ich singe. — Nem, nem dolgozom, éneklek.</div><div class=\"kurss-example\">Was tut Paul? — Mit csinál Paul?</div><div class=\"kurss-example\">Er spielt. — Ő játszik.</div><div class=\"kurss-example\">Was tut Marie? — Mit csinál Marie?</div><div class=\"kurss-example\">Sie singt. — Ő énekel.</div><div class=\"kurss-example\">Paul spielt, aber Marie singt. — Paul játszik, de Marie énekel.</div><div class=\"kurss-example\">Singt ihr? — Énekeltek?</div><div class=\"kurss-example\">Nein, wir singen nicht, wir arbeiten. — Nem, nem énekelünk, dolgozunk.</div><div class=\"kurss-example\">Was tun Paul und Marie? — Mit csinál Paul és Marie?</div><div class=\"kurss-example\">Sie fragen. — Ők kérdeznek.</div><div class=\"kurss-example\">Sie antworten nicht. — Ők nem válaszolnak.</div><div class=\"kurss-example\">Wer arbeitet? — Ki dolgozik?</div><div class=\"kurss-example\">Wir arbeiten. — Mi dolgozunk.</div><div class=\"kurss-example\">Wir rechnen und zeichnen. — Mi számolunk és rajzolunk.</div><div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen. — Ők jönnek, kérdeznek, válaszolnak, dolgoznak, játszanak, énekelnek és mennek.</div></div>\n            </section>",
  "kurssLesson2": "            <h3>2. lecke</h3>\n            <p class=\"kurss-lesson-intro\">A második lecke: párbeszédek, szavak, kiejtés, nyelvtan és fordítás.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Párbeszédek / mondatok</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">Spielst du?<br>Nein, ich spiele nicht, ich arbeite.</div>\n                  <div class=\"kurss-example\">Paul fragt nicht, er arbeitet.</div>\n                  <div class=\"kurss-example\">Arbeitest du?<br>Nein, ich arbeite nicht, ich singe.</div>\n                  <div class=\"kurss-example\">Was tut Paul?<br>Er spielt.</div>\n                  <div class=\"kurss-example\">Was tut Marie?<br>Sie singt.</div>\n                  <div class=\"kurss-example\">Paul spielt, aber Marie singt.</div>\n                  <div class=\"kurss-example\">Singt ihr?<br>Nein, wir singen nicht, wir arbeiten.</div>\n                  <div class=\"kurss-example\">Was tun Paul und Marie?<br>Sie fragen.<br>Sie antworten nicht.</div>\n                  <div class=\"kurss-example\">Wer arbeitet?<br>Wir arbeiten.<br>Wir rechnen und zeichnen.</div>\n                  <div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen.</div>\n                </div>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Szavak</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">spielen — játszani</div>\n                  <div class=\"kurss-example\">nein — nem</div>\n                  <div class=\"kurss-example\">nicht — nem</div>\n                  <div class=\"kurss-example\">arbeiten — dolgozni</div>\n                  <div class=\"kurss-example\">fragen — kérdezni</div>\n                  <div class=\"kurss-example\">was tut er? — mit csinál ő?</div>\n                  <div class=\"kurss-example\">was tun sie? — mit csinálnak ők?</div>\n                  <div class=\"kurss-example\">aber — de</div>\n                  <div class=\"kurss-example\">antworten — válaszolni</div>\n                  <div class=\"kurss-example\">rechnen — számolni</div>\n                  <div class=\"kurss-example\">zeichnen — rajzolni</div>\n                  <div class=\"kurss-example\">Marie — Mária</div>\n                </div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Kiejtés</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Az ich, nicht, rechnen, zeichnen szavakban a ch hangot lágyan ejtjük, nagyjából úgy, mint a h-t a magyar ihlet, technika szavakban.</div><div class=\"kurss-example\">Az arbeiten, zeichnen szavakban az ei kettőshangzót nagyjából úgy ejtjük, mint a magyar áj-t.</div><div class=\"kurss-example\">Az sp mássalhangzó-kapcsolatot úgy ejtjük, mint a magyar sp-t: spielen (spílen).</div><div class=\"kurss-example\">A tun igében az u-t minden személyben hosszan ejtjük.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Nyelvtan</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>1</span>Végződések e-vel</h4>\n                  <div class=\"lesson1-grammar-note\">Ha az igető t-re, d-re vagy chn-re végződik, ragozáskor az -st és a -t végződés elé e kerül.</div>\n                  <h5 class=\"lesson2-subtitle\">arbeiten</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich arbeite</div><div class=\"kurss-example\">du arbeitest</div><div class=\"kurss-example\">er arbeitet</div><div class=\"kurss-example\">sie arbeitet</div><div class=\"kurss-example\">wir arbeiten</div><div class=\"kurss-example\">ihr arbeitet</div><div class=\"kurss-example\">sie arbeiten</div></div>\n                  <h5 class=\"lesson2-subtitle\">rechnen</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich rechne</div><div class=\"kurss-example\">du rechnest</div><div class=\"kurss-example\">er rechnet</div><div class=\"kurss-example\">sie rechnet</div><div class=\"kurss-example\">wir rechnen</div><div class=\"kurss-example\">ihr rechnet</div><div class=\"kurss-example\">sie rechnen</div></div>\n                  <h5 class=\"lesson2-subtitle\">tun</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich tue</div><div class=\"kurss-example\">du tust</div><div class=\"kurss-example\">er tut</div><div class=\"kurss-example\">sie tut</div><div class=\"kurss-example\">wir tun</div><div class=\"kurss-example\">ihr tut</div><div class=\"kurss-example\">sie tun</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>2</span>Kérdőszó</h4>\n                  <div class=\"lesson1-grammar-note\">A kérdőszóval kezdődő kérdő mondatokban, például: mit? ki? melyik? miért? mi okból? stb., az ige közvetlenül a kérdőszó után áll.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Was tust du? — Mit csinálsz?</div><div class=\"kurss-example\">Was tut er? — Mit csinál ő (férfi)?</div><div class=\"kurss-example\">Was tut sie? — Mit csinál ő (nő)?</div><div class=\"kurss-example\">Was tun sie? — Mit csinálnak ők?</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>3</span>Tagadás nicht-tel</h4>\n                  <div class=\"lesson1-grammar-note\">Ha a nicht tagadás az igére vonatkozik, a tagadószó az ige után áll.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Er kommt nicht. — Ő nem jön.</div><div class=\"kurss-example\">Sie singen nicht. — Ők nem énekelnek.</div></div>\n                </section>\n              </div>\n            </details>\n                                    <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Fordítsd le</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson2-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"2. lecke: fordítókártya\">\n                    <span class=\"lesson1-training-progress\">2. lecke · Fordítsd le: 1 / 15</span>\n                    <span class=\"lesson1-training-text\">Ki kérdez?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Kattints a kártyára a német fordítás megtekintéséhez. A válasz után a következő kattintás a következő kártyát mutatja.</p>\n                </div>\n              </div>\n            </details>",
  "kurssLesson6": "\n    <h3>6. lecke</h3>\n    <p class=\"kurss-lesson-intro\">Számok, többes szám, umlautok és a főnevek többes számú alakjai.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Párbeszédek / mondatok</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier liegt ein Bleistift.</div><div class=\"kurss-example\">Dort liegen einige Messer.</div><div class=\"kurss-example\">Edgar nimmt ein Messer, zwei Messer, drei Messer.</div><div class=\"kurss-example\">Er legt die Messer wieder hin.</div><div class=\"kurss-example\">Alle Messer sind scharf.</div><div class=\"kurss-example\">Dann nimmt er wieder ein Messer.</div><div class=\"kurss-example\">Er macht das Messer auf.</div><div class=\"kurss-example\">Er nimmt den Bleistift.</div><div class=\"kurss-example\">Er spitzt den Bleistift an.</div><div class=\"kurss-example\">Er legt das Messer hin.</div><div class=\"kurss-example\">Er setzt sich und zeichnet.</div><div class=\"kurss-example\">Was zeichnet er? Er zeichnet einen Schlüssel.</div><div class=\"kurss-example\">Gertrud zeichnet ein Fenster und eine Tafel.</div><div class=\"kurss-example\">Anna zeichnet einen Garten.</div><div class=\"kurss-example\">Hier liegen vier Löffel.</div><div class=\"kurss-example\">Dort liegen fünf Nadeln.</div><div class=\"kurss-example\">Gertrud kommt und zählt die Löffel: das ist ein Löffel; das sind zwei, drei, vier Löffel.</div><div class=\"kurss-example\">Anna zählt die Nadeln: das ist eine Nadel; das sind zwei, drei, vier, fünf Nadeln.</div><div class=\"kurss-example\">Wieviel Nadeln sind hier?</div><div class=\"kurss-example\">Hier ist eine Nadel.</div><div class=\"kurss-example\">Dort sind zwei, drei, vier Nadeln.</div><div class=\"kurss-example\">Fünf Schlüssel sind hier.</div><div class=\"kurss-example\">Sechs Löffel sind dort.</div><div class=\"kurss-example\">Was ist das?</div><div class=\"kurss-example\">Das ist ein Hammer. Das sind fünf Hämmer.</div><div class=\"kurss-example\">Das ist ein Deckel. Das sind sechs Deckel.</div><div class=\"kurss-example\">Das ist ein Eimer. Das sind sieben Eimer.</div><div class=\"kurss-example\">Das ist ein Teller. Das sind acht Teller.</div><div class=\"kurss-example\">Das ist ein Wagen. Das sind neun Wagen.</div><div class=\"kurss-example\">Das ist ein Schlitten. Das sind zehn Schlitten.</div><div class=\"kurss-example\">Wie sind die Dinge?</div><div class=\"kurss-example\">Der Hammer ist klein. Die Hämmer sind klein.</div><div class=\"kurss-example\">Der Deckel ist groß. Die Deckel sind groß.</div><div class=\"kurss-example\">Der Eimer ist voll. Die Eimer sind voll.</div><div class=\"kurss-example\">Der Teller ist leer. Die Teller sind leer.</div><div class=\"kurss-example\">Der Wagen ist schwer. Die Wagen sind schwer.</div><div class=\"kurss-example\">Der Schlitten ist leicht. Die Schlitten sind leicht.</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Szavak</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">liegt — van, található, fekszik</div><div class=\"kurss-example\">der Bleistift (blájstift) — a ceruza</div><div class=\"kurss-example\">einige (ájnige) — néhány</div><div class=\"kurss-example\">hinlegen — letenni</div><div class=\"kurss-example\">legt hin — leteszi</div><div class=\"kurss-example\">wieder (víder) — újra, ismét</div><div class=\"kurss-example\">aufmachen — kinyitni</div><div class=\"kurss-example\">er macht auf — ő kinyitja</div><div class=\"kurss-example\">anspitzen (anspicen) — kihegyezni</div><div class=\"kurss-example\">er spitzt an — ő kihegyezi</div><div class=\"kurss-example\">sich setzen — leülni</div><div class=\"kurss-example\">setzt sich — leül</div><div class=\"kurss-example\">der Schlüssel (slüsszel) — a kulcs</div><div class=\"kurss-example\">das Fenster (fenszter) — az ablak</div><div class=\"kurss-example\">die Tafel (dí táfel) — a tábla</div><div class=\"kurss-example\">der Garten — a kert</div><div class=\"kurss-example\">der Löffel — a kanál</div><div class=\"kurss-example\">zählen (célen) — számlálni, megszámolni</div><div class=\"kurss-example\">die Nadel — a tű</div><div class=\"kurss-example\">was ist das — mi ez?</div><div class=\"kurss-example\">der Hammer — a kalapács</div><div class=\"kurss-example\">die Hämmer — a kalapácsok</div><div class=\"kurss-example\">der Deckel (dér dekel) — a fedő</div><div class=\"kurss-example\">der Teller — a tányér</div><div class=\"kurss-example\">der Wagen — a kocsi</div><div class=\"kurss-example\">der Schlitten — a szánkó, a szán</div><div class=\"kurss-example\">das Ding — a dolog</div><div class=\"kurss-example\">die Dinge — a dolgok</div><div class=\"kurss-example\">wie sind die Dinge? — milyenek a dolgok?</div><div class=\"kurss-example\">voll (fol) — tele</div><div class=\"kurss-example\">leer (lér) — üres</div><div class=\"kurss-example\">schwer (svér) — nehéz</div><div class=\"kurss-example\">leicht — könnyű</div><div class=\"kurss-example\">der Eimer — a vödör</div><div class=\"kurss-example\">wieviel (vífíl) — mennyi, hány</div><div class=\"kurss-example\">wieviel Nadeln — hány tű</div><div class=\"kurss-example\">hier (hír) — itt</div><div class=\"kurss-example\">dort — ott</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Kiejtés</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Az ä az a magánhangzó umlautos alakja, és rövid e-nek vagy hosszú é-nek ejtjük.</div><div class=\"kurss-example\">Példák: das Mädchen (méthen), die Bänke (dí benke), der Vater (dér fáter), die Väter (dí féter).</div><div class=\"kurss-example\">Az ü az u magánhangzó umlautos alakja, és úgy ejtjük, mint a magyar ü-t vagy ű-t.</div><div class=\"kurss-example\">Példák: fünf, der Schlüssel (slüsszel).</div><div class=\"kurss-example\">Az ö-t úgy ejtjük, mint a magyar ö-t vagy ő-t: der Löffel.</div><div class=\"kurss-example\">A kettőzött magánhangzó hosszú magánhangzót jelöl: leer (lér).</div><div class=\"kurss-example\">Az eu kettőshangzót oj-nak ejtjük: neun (nojn).</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Nyelvtan</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Nyelvtan és magyarázatok</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Az összetett ige hangsúlyos igekötője jelen időben elválik az igétől, és a mondat végére kerül.</div><div class=\"kurss-example\">Példák: hinlegen — er legt hin; aufmachen — er macht auf; anspitzen — er spitzt an.</div><div class=\"kurss-example\">Az egy számnévnek, ha főnévvel együtt használjuk, mindhárom nemben van alakja: hímnemben ein, nőnemben eine, semlegesnemben ein.</div><div class=\"kurss-example\">Példák: ein Schüler — egy tanuló; eine Schülerin — egy tanulólány; ein Kind — egy gyermek.</div><div class=\"kurss-example\">Számok: eins, zwei, drei, vier (fír), fünf, sechs (zeksz), sieben (zíben), acht, neun (nojn), zehn (cén).</div><div class=\"kurss-example\">A létigének a németben egyes és többes számú alakja is van: der Schüler ist klein; die Schüler sind klein.</div><div class=\"kurss-example\">A magyarban a mutató névmás számban változik, a németben azonban csak egy alakot használunk: das.</div><div class=\"kurss-example\">Példák: ez egy kalapács — das ist ein Hammer; ez egy tű — das ist eine Nadel; ezek kalapácsok — das sind Hämmer; ezek tűk — das sind Nadeln.</div><div class=\"kurss-example\">Der Wagen — kocsi és der Schlitten — szánkó: a németben ezeket a szavakat egyes és többes számban is használjuk.</div><div class=\"kurss-example\">Az -er, -el, -en végű hím- és semlegesnemű főnevek többes számban gyakran nem kapnak végződést.</div><div class=\"kurss-example\">Példák: der Hammer — die Hämmer; der Garten — die Gärten; das Fenster — die Fenster; das Messer — die Messer.</div><div class=\"kurss-example\">Az -el, -er végű nőnemű főnevek többes számban -n végződést kapnak.</div><div class=\"kurss-example\">Példák: die Nadel — die Nadeln; die Feder — die Federn.</div><div class=\"kurss-example\">Kivételek: die Mutter (anya) — die Mütter (anyák); die Tochter (lány) — die Töchter (lányok).</div><div class=\"kurss-example\">A határozatlan névelőnek nincs többes száma: das ist ein Wagen — das sind Wagen; das ist eine Nadel — das sind Nadeln.</div><div class=\"kurss-example\">Kijelentő mondatban az igei állítmány a második helyen áll: er legt den Schlüssel hin; dann legt er den Schlüssel hin.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Fordítsd le</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson6-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"6. lecke: fordítókártya\"><span class=\"lesson1-training-progress\">6. lecke · Fordítsd le: 1 / 21</span><span class=\"lesson1-training-text\">Paul elvesz egy ceruzát, és rajzol.</span></button><p class=\"lesson1-training-hint\">Kattints a kártyára a német fordítás megtekintéséhez. A válasz után a következő kattintás a következő kártyát mutatja.</p></div></div>\n    </details>\n  ",
  "kurssLesson5": "\n    <h3>5. lecke</h3>\n    <p class=\"kurss-lesson-intro\">Wen?, tárgyeset, sitzen, fragen és az -in végződés.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Párbeszédek / mondatok</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">Wer sitzt und fragt? Der Lehrer sitzt und fragt.</div>\n        <div class=\"kurss-example\">Wer steht und antwortet? Der Schüler steht und antwortet.</div>\n        <div class=\"kurss-example\">Wie antwortet der Schüler? Der Schüler antwortet gut.</div>\n        <div class=\"kurss-example\">Wen lobt der Lehrer? Der Lehrer lobt den Schüler.</div>\n        <div class=\"kurss-example\">Wie ist der Schüler? Der Schüler ist klein.</div>\n        <div class=\"kurss-example\">Ist der Schüler klein oder groß? Er ist klein.</div>\n        <div class=\"kurss-example\">Wen fragt die Lehrerin? Die Lehrerin fragt die Schülerin.</div>\n        <div class=\"kurss-example\">Wie antwortet die Schülerin? Die Schülerin antwortet schlecht.</div>\n        <div class=\"kurss-example\">Was tut die Lehrerin? Sie tadelt die Schülerin.</div>\n        <div class=\"kurss-example\">Die Schülerin ist nicht klein, sie ist groß.</div>\n        <div class=\"kurss-example\">Ein Kind spielt. Das Kind ist artig.</div>\n        <div class=\"kurss-example\">Die Mutter liebt das Kind. Der Vater lobt das Kind.</div>\n      </div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Szavak</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">sitzen (zicen) — ülni</div>\n        <div class=\"kurss-example\">fragen (frágen) — kérdezni</div>\n        <div class=\"kurss-example\">der Lehrer (dér lérer) — a tanár</div>\n        <div class=\"kurss-example\">gut (gút) — jól</div>\n        <div class=\"kurss-example\">wen (vén) — kit</div>\n        <div class=\"kurss-example\">loben — dicsérni</div>\n        <div class=\"kurss-example\">der Schüler (sűler) — a tanuló</div>\n        <div class=\"kurss-example\">klein — kicsi</div>\n        <div class=\"kurss-example\">groß (grósz) — nagy</div>\n        <div class=\"kurss-example\">die Lehrerin — a tanárnő</div>\n        <div class=\"kurss-example\">die Schülerin — a tanulólány</div>\n        <div class=\"kurss-example\">schlecht (sleht) — rosszul</div>\n        <div class=\"kurss-example\">tadeln — szidni</div>\n        <div class=\"kurss-example\">oder (óder) — vagy</div>\n        <div class=\"kurss-example\">das Kind (kint) — a gyermek</div>\n        <div class=\"kurss-example\">artig (ártih) — szófogadó, jó</div>\n        <div class=\"kurss-example\">die Mutter — az anya</div>\n        <div class=\"kurss-example\">lieben (líben) — szeretni</div>\n        <div class=\"kurss-example\">der Vater (fáter) — az apa</div>\n      </div></div>\n    </details>\n\n        <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Kiejtés</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">A tz kettőzött z hang, és úgy ejtjük, mint a magyar c-t: sitzen (zicen).</div>\n        <div class=\"kurss-example\">A v-t a német szavakban f-nek ejtjük: der Vater (fáter).</div>\n        <div class=\"kurss-example\">A ß neve eszcet, és úgy ejtjük, mint a magyar sz-t: groß (grósz), weiß (vájsz).</div>\n      </div></div>\n    </details>\n\n<details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Nyelvtan</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Alanyeset és tárgyeset</h4><div class=\"lesson1-grammar-note\">A magyarban az alanyeset a ki? / mi? kérdésre felel, a tárgyeset pedig a kit? / mit? kérdésre.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">A németben alanyesetben a kérdés személyekre wer?, tárgyakra was?.</div><div class=\"kurss-example\">Tárgyesetben a kérdés személyekre wen?, tárgyakra was?.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">A névelők változása tárgyesetben</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Akkusativ: den Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">sitzen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich sitze</div><div class=\"kurss-example\">du sitzt</div><div class=\"kurss-example\">er/sie/es sitzt</div><div class=\"kurss-example\">wir sitzen</div><div class=\"kurss-example\">ihr sitzt</div><div class=\"kurss-example\">sie sitzen</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">fragen + tárgyeset</h4><div class=\"lesson1-grammar-note\">A fragen ige a németben tárgyesetet vonz.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wen fragt der Lehrer?</div><div class=\"kurss-example\">Der Lehrer fragt den Schüler.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Az -in végződés</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Sok nőnemű főnevet az -in végződéssel képzünk.</div><div class=\"kurss-example\">die Lehrerin</div><div class=\"kurss-example\">die Schülerin</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Az ige helye</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Kijelentő mondatban az ige a második helyen áll.</div><div class=\"kurss-example\">Dann geht das Mädchen hinaus und arbeitet.</div><div class=\"kurss-example\">Das Mädchen geht dann hinaus und arbeitet.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Fordítsd le</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson5-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"5. lecke: fordítókártya\"><span class=\"lesson1-training-progress\">5. lecke · Fordítsd le: 1 / 16</span><span class=\"lesson1-training-text\">Kit szeret az apa?</span></button><p class=\"lesson1-training-hint\">Kattints a kártyára a német fordítás megtekintéséhez. A válasz után a következő kattintás a következő kártyát mutatja.</p></div></div>\n    </details>\n  ",
  "kurssLesson4": "            <h3>4. lecke</h3>\n            <p class=\"kurss-lesson-intro\">Tárgyeset, nehmen, hinlegen, hinausgehen és melléknevek.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Párbeszédek / mondatok</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Paul kommt und nimmt einen Federhalter.</div><div class=\"kurss-example\">Er zeigt den Federhalter.</div><div class=\"kurss-example\">Er fragt: „Wie ist der Federhalter?“</div><div class=\"kurss-example\">Olga antwortet: „Der Federhalter ist schwarz.“</div><div class=\"kurss-example\">Ist der Federhalter weiß? Nein, der Federhalter ist nicht weiß, er ist schwarz.</div><div class=\"kurss-example\">Marie kommt und nimmt eine Feder.</div><div class=\"kurss-example\">Sie fragt: „Wie ist die Feder?“</div><div class=\"kurss-example\">Olga antwortet: „Die Feder ist spitz.“</div><div class=\"kurss-example\">Ist die Feder stumpf? Nein, die Feder ist nicht stumpf, sie ist spitz.</div><div class=\"kurss-example\">Was legt das Mädchen hin? Es legt die Feder hin.</div><div class=\"kurss-example\">Was nimmst du? Ich nehme ein Messer.</div><div class=\"kurss-example\">Wie ist das Messer? Das Messer ist scharf.</div><div class=\"kurss-example\">Ist das Messer stumpf? Nein, es ist nicht stumpf, es ist scharf.</div><div class=\"kurss-example\">Was legst du hin? Ich lege das Messer, die Feder und den Federhalter hin.</div><div class=\"kurss-example\">Dann gehe ich hinaus und arbeite.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Szavak</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">nehmen (némen) — venni, elvenni</div><div class=\"kurss-example\">er nimmt (nimt) — ő veszi</div><div class=\"kurss-example\">der Federhalter (dér féderhalter) — a tollszár</div><div class=\"kurss-example\">einen Federhalter — egy tollszárat</div><div class=\"kurss-example\">zeigen — mutatni</div><div class=\"kurss-example\">schwarz (svarc) — fekete</div><div class=\"kurss-example\">weiß (vájsz) — fehér</div><div class=\"kurss-example\">die Feder (dí féder) — a toll</div><div class=\"kurss-example\">eine Feder — egy tollat</div><div class=\"kurss-example\">spitz (spic) — hegyes</div><div class=\"kurss-example\">hinlegen — letenni</div><div class=\"kurss-example\">legt hin — leteszi</div><div class=\"kurss-example\">das Mädchen (méthen) — a lány</div><div class=\"kurss-example\">das Messer — a kés</div><div class=\"kurss-example\">ein Messer — egy kést</div><div class=\"kurss-example\">scharf — éles</div><div class=\"kurss-example\">stumpf (stumpf) — tompa</div><div class=\"kurss-example\">dann — aztán, akkor</div><div class=\"kurss-example\">hinaus — ki, kifelé</div><div class=\"kurss-example\">hinausgehen — kimenni</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Kiejtés</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Az -en, -er, -el végződések hangsúlytalanok, ezért ezekben a végződésekben az e alig hallható: kommen, nehmen, der Federhalter.</div><div class=\"kurss-example\">A németben a h lehet hang is, és az előtte álló magánhangzó hosszúságának jele is.</div><div class=\"kurss-example\">Ha a h hosszúságjel, nem ejtjük hangként: nehmen (némen).</div><div class=\"kurss-example\">Ha a magánhangzót csak egy mássalhangzó követi, a magánhangzót hosszan ejtjük: die (dí) Feder (féder), den (dén).</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Nyelvtan</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Tárgyeset</h4><div class=\"lesson1-grammar-note\">Nőnemben és semlegesnemben a tárgyeset megegyezik az alanyesettel. Csak a hímnem változik.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Nominativ: ein Federhalter, eine Feder, ein Messer.</div><div class=\"kurss-example\">Akkusativ: einen Federhalter, eine Feder, ein Messer.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>nehmen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich nehme</div><div class=\"kurss-example\">du nimmst</div><div class=\"kurss-example\">er/sie nimmt</div><div class=\"kurss-example\">wir nehmen</div><div class=\"kurss-example\">ihr nehmt</div><div class=\"kurss-example\">sie nehmen</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Névmások</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er — hímnem</div><div class=\"kurss-example\">sie — nőnem</div><div class=\"kurss-example\">es — semlegesnem</div><div class=\"kurss-example\">többes számban — sie</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Elváló igekötős igék</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">hinlegen → ich lege das Messer hin</div><div class=\"kurss-example\">hinausgehen → Marie geht hinaus</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>Melléknevek</h4><div class=\"lesson1-grammar-note\">Ha a melléknév a mondatban állítmány, nem változik sem nemben, sem számban.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist klein</div><div class=\"kurss-example\">die Feder ist klein</div><div class=\"kurss-example\">das Messer ist klein</div><div class=\"kurss-example\">die Messer sind klein</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>6</span>Tagadás nicht-tel</h4><div class=\"lesson1-grammar-note\">Ha a nicht melléknevet tagad, a tagadott szó előtt áll.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist nicht weiß</div><div class=\"kurss-example\">das Messer ist nicht scharf</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>7</span>-chen / -lein</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">A -chen és -lein végű főnevek semlegesneműek: das Mädchen.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Fordítsd le</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson4-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"4. lecke: fordítókártya\"><span class=\"lesson1-training-progress\">4. lecke · Fordítsd le: 1 / 16</span><span class=\"lesson1-training-text\">A lány elvesz egy tollszárat.</span></button><p class=\"lesson1-training-hint\">Kattints a kártyára a német fordítás megtekintéséhez. A válasz után a következő kattintás a következő kártyát mutatja.</p></div></div></details>",
  "kurssLesson3": "            <h3>3. lecke</h3>\n            <p class=\"kurss-lesson-intro\">A harmadik lecke: párbeszédek, szavak, kiejtés, nyelvtan és fordítás.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Párbeszédek / mondatok</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wer rechnet und zeichnet?<br>Wir rechnen und zeichnen.</div><div class=\"kurss-example\">Wer kommt?<br>Paul und Anna kommen.</div><div class=\"kurss-example\">Was steht hier?<br>Hier steht ein Tisch.</div><div class=\"kurss-example\">Was steht dort?<br>Dort steht eine Bank.</div><div class=\"kurss-example\">Was liegt hier?<br>Hier liegt ein Buch.</div><div class=\"kurss-example\">Was liegt dort?<br>Dort liegt ein Heft.</div><div class=\"kurss-example\">Was hängt hier?<br>Hier hängt ein Bild.</div><div class=\"kurss-example\">Was hängt dort?<br>Dort hängt eine Tafel.</div><div class=\"kurss-example\">Wie ist das Buch?<br>Das Buch ist dick.</div><div class=\"kurss-example\">Wie ist das Heft?<br>Das Heft ist dünn.</div><div class=\"kurss-example\">Wie ist die Bank?<br>Die Bank ist niedrig.</div><div class=\"kurss-example\">Wie ist der Tisch?<br>Der Tisch ist hoch.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Szavak</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wer — ki</div><div class=\"kurss-example\">was — mi</div><div class=\"kurss-example\">hier — itt</div><div class=\"kurss-example\">dort — ott</div><div class=\"kurss-example\">der Tisch — az asztal</div><div class=\"kurss-example\">ein Tisch — egy asztal</div><div class=\"kurss-example\">die Bank — a pad</div><div class=\"kurss-example\">eine Bank — egy pad</div><div class=\"kurss-example\">liegen — feküdni (vízszintesen lenni)</div><div class=\"kurss-example\">liegt hier ein Buch? — van itt egy könyv?</div><div class=\"kurss-example\">das Buch — a könyv</div><div class=\"kurss-example\">ein Buch — egy könyv</div><div class=\"kurss-example\">hängen — lógni</div><div class=\"kurss-example\">das Bild — a kép</div><div class=\"kurss-example\">ein Bild — egy kép</div><div class=\"kurss-example\">die Tafel — a tábla</div><div class=\"kurss-example\">eine Tafel — egy tábla</div><div class=\"kurss-example\">wie — milyen</div><div class=\"kurss-example\">ist — van</div><div class=\"kurss-example\">dick — vastag, kövér</div><div class=\"kurss-example\">das Heft — a füzet</div><div class=\"kurss-example\">ein Heft — egy füzet</div><div class=\"kurss-example\">dünn — vékony, sovány</div><div class=\"kurss-example\">niedrig — alacsony</div><div class=\"kurss-example\">hoch — magas</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Kiejtés</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">A hosszú í hangot a németben ie jelöli: liegen (lígen), hier (hír), wie (ví).</div><div class=\"kurss-example\">A ck kettőzött k: dick (dikk).</div><div class=\"kurss-example\">A melléknevekben és határozószókban az -ig végződés enyhe -ich-nek hangzik: niedrig (nídrih).</div><div class=\"kurss-example\">Ha az -ig végződéshez e járul: -ige, akkor a g-t tiszta g-nek ejtjük: niedrige (nídrige) Bänke.</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Nyelvtan</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Az alany</h4><div class=\"lesson1-grammar-note\">Az alany a németben a wer? / was? kérdésre felel, és alanyesetben áll.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">A wer? kérdéssel személyekre kérdezünk.</div><div class=\"kurss-example\">A was? kérdéssel tárgyakra kérdezünk.</div><div class=\"kurss-example\">Wer singt? — Sie singt.</div><div class=\"kurss-example\">Was liegt hier? — Hier liegt ein Buch.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Névelők</h4><div class=\"lesson1-grammar-note\">A németben a főneveknek 3 nemük van: hímnem, nőnem és semlegesnem. A főnevek előtt általában egy kis szó áll, amelyet névelőnek nevezünk. Ezt a szócskát külön nem fordítjuk le.</div><h5 class=\"lesson2-subtitle\">A határozott névelő</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">hímnem — der</div><div class=\"kurss-example\">nőnem — die</div><div class=\"kurss-example\">semlegesnem — das</div><div class=\"kurss-example\">Többes számban a határozott névelő mindhárom nemben die.</div><div class=\"kurss-example\">der Tisch — die Tische</div><div class=\"kurss-example\">die Bank — die Bänke</div><div class=\"kurss-example\">das Heft — die Hefte</div></div><h5 class=\"lesson2-subtitle\">A határozatlan névelő</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">hímnem — ein</div><div class=\"kurss-example\">nőnem — eine</div><div class=\"kurss-example\">semlegesnem — ein</div><div class=\"kurss-example\">A határozatlan névelőnek nincs többes száma.</div><div class=\"kurss-example\">ein Tisch — Tische</div><div class=\"kurss-example\">ein Heft — Hefte</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Tulajdonnevek</h4><div class=\"lesson1-grammar-note\">Tulajdonnevek előtt nem használunk névelőt.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans spielt, aber Marie singt.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Az ige helye</h4><div class=\"lesson1-grammar-note\">Kijelentő mondatban az ige a második helyen áll.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier hängt eine Karte.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>stehen / liegen / hängen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">A németben a függőlegesen álló tárgyakról azt mondjuk, hogy állnak:<br>der Tisch steht<br>die Bank steht</div><div class=\"kurss-example\">A vízszintes helyzetben lévő tárgyakról azt mondjuk, hogy fekszenek:<br>das Buch liegt<br>das Heft liegt</div><div class=\"kurss-example\">A tárgyak lóghatnak is:<br>die Karte hängt<br>die Tafel hängt</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Fordítsd le</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson3-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"3. lecke: fordítókártya\"><span class=\"lesson1-training-progress\">3. lecke · Fordítsd le: 1 / 22</span><span class=\"lesson1-training-text\">Számolsz?</span></button><p class=\"lesson1-training-hint\">Kattints a kártyára a német fordítás megtekintéséhez. A válasz után a következő kattintás a következő kártyát mutatja.</p></div></div></details>",
  "kurssLesson7": "            <h3>7. lecke</h3>\n            <p class=\"kurss-lesson-intro\">A hetedik lecke: felszólító mód, megszólítási forma és többes szám.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Párbeszédek / mondatok</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans, singe ein Lied! Was tust du? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans und Olga, singt ein Lied! Was tut ihr? Wir singen ein Lied.</div><div class=\"kurss-example\">Fräulein Müller, singen Sie, bitte, ein Lied! Was tun Sie? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans, zähle die Teller! Was tut Hans? Er zählt die Teller.</div><div class=\"kurss-example\">Hans und Olga, zählt die Teller! Was tun Hans und Olga? Sie zählen die Teller.</div><div class=\"kurss-example\">Fräulein Müller, zählen Sie, bitte, die Teller!</div><div class=\"kurss-example\">Hans, öffne das Fenster! Was tut Hans? Er öffnet das Fenster.</div><div class=\"kurss-example\">Hans und Olga, öffnet die Fenster! Was tun Hans und Olga? Sie öffnen die Fenster.</div><div class=\"kurss-example\">Fräulein Müller, öffnen Sie, bitte, alle Fenster!</div><div class=\"kurss-example\">Fräulein Müller öffnet alle Fenster.</div><div class=\"kurss-example\">Das ist der Spiegel. Das sind die Spiegel.</div><div class=\"kurss-example\">Das ist der Lappen. Das sind die Lappen.</div><div class=\"kurss-example\">Das ist der Spaten. Das sind die Spaten.</div><div class=\"kurss-example\">Das ist der Besen. Das sind die Besen.</div><div class=\"kurss-example\">Das ist die Schaufel. Das sind die Schaufeln.</div><div class=\"kurss-example\">Das ist die Schüssel. Das sind die Schüsseln.</div><div class=\"kurss-example\">Das ist das Zimmer. Das sind die Zimmer.</div><div class=\"kurss-example\">Das ist das Ufer. Das sind die Ufer.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Szavak</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">singen — énekelni</div><div class=\"kurss-example\">singe — énekelj</div><div class=\"kurss-example\">singt — énekeljetek</div><div class=\"kurss-example\">singen Sie — énekeljen (Ön)</div><div class=\"kurss-example\">das Lied (dasz lít) — a dal</div><div class=\"kurss-example\">Sie — Ön</div><div class=\"kurss-example\">zählen — számlálni</div><div class=\"kurss-example\">das Fräulein (frojlájn) — a kisasszony</div><div class=\"kurss-example\">der Müller — a molnár</div><div class=\"kurss-example\">öffnen — kinyitni</div><div class=\"kurss-example\">das Fenster (fenszter) — az ablak</div><div class=\"kurss-example\">alle — mindenki, mind</div><div class=\"kurss-example\">der Spiegel (spígel) — a tükör</div><div class=\"kurss-example\">der Lappen — a rongy, a törlőrongy</div><div class=\"kurss-example\">der Spaten — az ásó</div><div class=\"kurss-example\">der Besen — a seprű</div><div class=\"kurss-example\">die Schaufel — a lapát</div><div class=\"kurss-example\">die Schüssel — a tál</div><div class=\"kurss-example\">das Zimmer — a szoba</div><div class=\"kurss-example\">das Ufer (úfer) — a part</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Kiejtés</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">A szó vagy szótag elején az sp-t úgy ejtjük, mint a magyar sp-t: der Spiegel (dér spígel).</div><div class=\"kurss-example\">Az sch-t úgy ejtjük, mint a magyar s-t: die Schaufel (dí saufel), die Schüssel (dí süsszel).</div><div class=\"kurss-example\">Az äu kettőshangzót úgy ejtjük, mint a magyar oj-t: das Fräulein (dasz frojlájn).</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Nyelvtan</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Felszólító mód</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Az egyes szám 2. személyű felszólító alak az ige egyes szám 2. személyű alakjának felel meg az -st személyrag nélkül, -e végződéssel.</div><div class=\"kurss-example\">Példák: antworte!, arbeite!, öffne!, zeichne!</div><div class=\"kurss-example\">Nagyon gyakran elmarad az -e végződés, ha a felszólító alak egy szótagú: geh!, steh!, komm!, tu!, sing!, frag!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Többes számú felszólítás</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">A többes szám 2. személyű felszólító alak megegyezik a jelen idő többes szám 2. személyű alakjával, de névmás nélkül használjuk.</div><div class=\"kurss-example\">Példák: antwortet!, arbeitet!, öffnet!, zeichnet!, geht!, steht!, tut!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Megszólítás Sie-vel</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Az „Ön” megszólítási forma megegyezik a többes szám 3. személyével. A Sie névmást nagy kezdőbetűvel írjuk, és az ige után áll.</div><div class=\"kurss-example\">Példák: antworten Sie!, arbeiten Sie!, öffnen Sie!, zeichnen Sie!, gehen Sie!, stehen Sie!, tun Sie!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>öffnen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Az öffnen igénél a könnyebb kiejtés kedvéért egyes szám 2. és 3. személyben, valamint többes szám 2. személyben a tő és a végződés közé e kerül: du öffnest, er öffnet, ihr öffnet.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Übung / Gyakorlat</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson7-exercise-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"7. lecke: gyakorlókártya\"><span class=\"lesson1-training-progress\">7. lecke · Übung: 1 / 16</span><span class=\"lesson1-training-text\">fragen — kérdezni</span></button><p class=\"lesson1-training-hint\">Koppints a kártyára a felszólító alakok megtekintéséhez.</p></div></div></details>",
  "kurssLesson1": "            <h3>1. lecke</h3>\n            <p class=\"kurss-lesson-intro\">Az első lecke: igék jelen időben, szavak, kiejtés, nyelvtan és fordítás.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Igék jelen időben</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info\">Az igék és ragozásuk jelen időben.</div>\n                <div class=\"lesson1-verb-cards\">\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>kommen — jönni</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>komme</strong><span>én jövök</span><span>du</span><strong>kommst</strong><span>te jössz</span><span>er / sie</span><strong>kommt</strong><span>ő jön</span><span>wir</span><strong>kommen</strong><span>mi jövünk</span><span>ihr</span><strong>kommt</strong><span>ti jöttök</span><span>sie / Sie</span><strong>kommen</strong><span>ők jönnek / Ön jön</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>gehen — menni</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>gehe</strong><span>én megyek</span><span>du</span><strong>gehst</strong><span>te mész</span><span>er / sie</span><strong>geht</strong><span>ő megy</span><span>wir</span><strong>gehen</strong><span>mi megyünk</span><span>ihr</span><strong>geht</strong><span>ti mentek</span><span>sie / Sie</span><strong>gehen</strong><span>ők mennek / Ön megy</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>stehen — állni</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>stehe</strong><span>én állok</span><span>du</span><strong>stehst</strong><span>te állsz</span><span>er / sie</span><strong>steht</strong><span>ő áll</span><span>wir</span><strong>stehen</strong><span>mi állunk</span><span>ihr</span><strong>steht</strong><span>ti álltok</span><span>sie / Sie</span><strong>stehen</strong><span>ők állnak / Ön áll</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>singen — énekelni</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>singe</strong><span>én énekelek</span><span>du</span><strong>singst</strong><span>te énekelsz</span><span>er / sie</span><strong>singt</strong><span>ő énekel</span><span>wir</span><strong>singen</strong><span>mi énekelünk</span><span>ihr</span><strong>singt</strong><span>ti énekeltek</span><span>sie / Sie</span><strong>singen</strong><span>ők énekelnek / Ön énekel</span></div>\n                  </article>\n                </div>\n                <section class=\"lesson1-block\">\n                  <h4>Példák</h4>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Stehst du?<br>Ja, ich stehe.</div><div class=\"kurss-example\">Steht Albert?<br>Ja, er steht.</div><div class=\"kurss-example\">Steht Marta?<br>Ja, sie steht.</div><div class=\"kurss-example\">Wer kommt und singt?<br>Albert und Marta kommen und singen.</div><div class=\"kurss-example\">Geht ihr?<br>Ja, wir gehen.</div><div class=\"kurss-example\">Wer steht und singt?<br>Albert und Marta stehen und singen.</div></div>\n                </section>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Szavak</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info lesson1-vardini-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>A szavak hozzávetőleges kiejtése zárójelben, magyar betűkkel van megadva.<br>Ez a következő leckékben is így lesz.</span></div>\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wir (vír) — mi</div><div class=\"kurss-example\">A „wir” szóban az i betűt hosszan ejtjük.</div><div class=\"kurss-example\">kommen (komen) — jönni</div><div class=\"kurss-example\">gehen (gé-en) — menni</div><div class=\"kurss-example\">stehen (sté-en) — állni</div><div class=\"kurss-example\">singen (zingen) — énekelni</div><div class=\"kurss-example\">du (dú) kommst — te jössz</div><div class=\"kurss-example\">er (ér) kommt — ő (férfi) jön</div><div class=\"kurss-example\">sie (zí) kommt — ő (nő) jön</div><div class=\"kurss-example\">wer (vér) — ki?</div><div class=\"kurss-example\">ja (já) — igen</div></div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Kiejtés</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">A szavak helyes kiejtése magyar betűkkel szerepel a leckékben.</div><div class=\"kurss-example\">Wir (vír) — mi. A wir szóban az i-t mindig hosszan ejtjük.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Nyelvtan</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>∞</span>Főnévi igenév</h4><div class=\"lesson1-grammar-note\">Az ige alapalakja. A főnévi igenév általában -en végű.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">kommen</div><div class=\"kurss-example\">gehen</div><div class=\"kurss-example\">stehen</div><div class=\"kurss-example\">singen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♟</span>Jelen idejű végződések</h4><div class=\"lesson1-ending-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><div class=\"lesson1-ending-info-body\"><p><strong>Vedd le az <span class=\"lesson1-ending-accent\">-en</span> végződést az ige alapalakjáról, és tedd hozzá a személyragot.</strong></p><p>Példa: kommen → komm + végződés</p><div class=\"lesson1-ending-process\" aria-label=\"A jelen idejű alakok képzésének menete\"><div class=\"lesson1-ending-step\"><strong>kommen</strong><span>alapalak</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>vedd le <span class=\"lesson1-ending-accent\">-en</span></strong><span>marad a tő</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>komm</strong><span>tő</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>tedd hozzá a végződést</strong><span>e / st / t</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-results\"><div>komm + <span class=\"lesson1-ending-accent\">e</span> = <strong>komme</strong></div><div>komm + <span class=\"lesson1-ending-accent\">st</span> = <strong>kommst</strong></div><div>komm + <span class=\"lesson1-ending-accent\">t</span> = <strong>kommt</strong></div></div></div></div></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich → -e</div><div class=\"kurss-example\">du → -st</div><div class=\"kurss-example\">er / sie → -t</div><div class=\"kurss-example\">wir → -en</div><div class=\"kurss-example\">ihr → -t</div><div class=\"kurss-example\">sie → -en</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>●</span>Példák</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich komme</div><div class=\"kurss-example\">du kommst</div><div class=\"kurss-example\">er kommt</div><div class=\"kurss-example\">wir kommen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>?</span>Kérdő mondatok</h4><div class=\"lesson1-grammar-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>A német kérdő mondatban az ige általában az első helyre kerül.</span></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Magyarul:<br>Te jössz.<br>Jössz?</div><div class=\"kurss-example\">Németül:<br>Du kommst.<br>Kommst du?</div><div class=\"kurss-example\">du kommst — te jössz<br>kommst du? — jössz?</div><div class=\"kurss-example\">er singt — ő énekel<br>singt er? — énekel ő?</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♣</span>Személybeli különbség</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er kommt — ő (férfi) jön</div><div class=\"kurss-example\">sie kommt — ő (nő) jön</div><div class=\"kurss-example\">sie kommen — ők jönnek</div></div></section>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Fordítsd le</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson1-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"1. lecke: gyakorlókártya\">\n                    <span class=\"lesson1-training-progress\">1. lecke · Fordítsd le: 1 / 11</span>\n                    <span class=\"lesson1-training-text\">Jössz?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Kattints a kártyára a német fordítás megtekintéséhez. A válasz után a következő kattintás a következő kártyát mutatja.</p>\n                </div>\n              </div>\n            </details>"
};

